                long kind = VecNth(rt, rt.Slot(rt.R(at + i), 1), 0, Val.Nil);
                int kbase = rt.Mark();
                int kindi = rt.Push(kind);
                long sp = LitKeyword1(rt, "splice");
                bool hit = ValEq(rt, rt.R(kindi), sp);
                rt.PopTo(kbase);
                if (hit) {
                    return true;
                }
