        int names = rt.Mark();
        for (int i = 0; i < n; i++) {
            int nk = rt.SinkOpen();
            MsgVal(rt, nk, rt.Slot(VecNth(rt, rt.R(evi), i, Val.Nil), 0));
            long one = rt.SinkString(nk);
            rt.SinkClose(nk);
            rt.Push(one);
        }
