        int sk = rt.SinkOpen();
        MsgLit(rt, sk, "no reader for the tag #");
        MsgVal(rt, sk, rt.R(tagi));
        if (n > 0) {
            MsgLit(rt, sk, "; this project can read ");
            for (int j = 0; j < n; j++) {
                if (j > 0) {
                    MsgLit(rt, sk, ", ");
                }
                rt.SinkPut(sk, 35);
                MsgVal(rt, sk, rt.R(names + j));
            }
