            MsgLit(rt, sk, "; this project has no reader tags");
        }
        MsgLit(rt, sk, ". A tag is bound per PROJECT, not per namespace: add it under :flint/tag-readers in deps.edn, mapping the tag NAME to the VAR that reads it -- {");
        MsgVal(rt, sk, rt.R(tagi));
        MsgLit(rt, sk, " my.ns/read-it}. Using another project's tag is opt-in, which is why yours are not in scope here by default (DECISIONS.md#reader-tags). To make a tagged literal as a VALUE instead, call (tagged-literal '");
        MsgVal(rt, sk, rt.R(tagi));
        MsgLit(rt, sk, " form); to read one from data, use clojure.edn/read-string with :readers or :default.");
        rt.PopTo(@base);
        return RdFailSink(rt, sti, sk);
    }
    /// A flint-only tag in a PORTABLE file.
