            rt.PopTo(@base);
            rt.Push(coll);
            StampStash(rt, sti, @base, line, col, true);
        } else if (c == 123) {
            st = ReadDelimited(rt, sti, 125);
            if (st != RsOk) {
                return st;
            }
            int mn = DelimitedCount(rt, @base);
            if (RdFlag(rt, sti, RdsDefer) && SizeConditional(rt, @base + 1, mn)) {
                long kvs = VecFromRoots(rt, @base + 1, mn);
                rt.PopTo(@base);
                int kvi = rt.Push(kvs);
                int ncp = rt.Push(Val.Nil);
                PushConditional(rt, sti, "map", line, col, ncp, kvi);
                long node = rt.R(ncp + 1);
                rt.PopTo(@base);
                rt.Push(node);
            } else {
                if ((mn % 2) != 0) {
                    rt.PopTo(@base);
                    return RdFailLit(rt, sti, "map literal needs an even number of forms");
                }
                long flat = VecFromRoots(rt, @base + 1, mn);
                long om = OrderedMap(rt, flat);
                rt.PopTo(@base);
                rt.Push(om);
            }
        } else if (c == 41) {
            return RdFailLit(rt, sti, "unexpected )");
        } else if (c == 93) {
            return RdFailLit(rt, sti, "unexpected ]");
        } else if (c == 125) {
            return RdFailLit(rt, sti, "unexpected }");
        } else if (c == 34) {
            st = ReadStringLit(rt, sti);
        } else if (c == 92) {
            st = ReadCharLit(rt, sti);
        } else if (c == 39) {
            RdNext(rt, sti);
            long q = LitSymbol1(rt, "quote");
            st = ReadWrapped(rt, sti, q);
        } else if (c == 64) {
            RdNext(rt, sti);
            long dr = LitSymbol(rt, "clojure.core", "deref");
            st = ReadWrapped(rt, sti, dr);
        } else if (c == 94) {
            st = ReadMeta(rt, sti);
        } else if (c == 96) {
            st = ReadSyntaxQuote(rt, sti);
        } else if (c == 126) {
            RdNext(rt, sti);
            if (RdPeek(rt, sti) == 64) {
                RdNext(rt, sti);
                long us = LitSymbol(rt, "clojure.core", "unquote-splicing");
                st = ReadWrapped(rt, sti, us);
            } else {
                long uq = LitSymbol(rt, "clojure.core", "unquote");
                st = ReadWrapped(rt, sti, uq);
            }
        } else if (c == 35) {
            st = ReadDispatch(rt, sti, line, col);
        } else {
            st = ReadSymbolic(rt, sti);
        }
        if (st != RsOk) {
            return st;
        }
        // EVERY meta-able form, and the stash's positions on a sequence.
        StampStash(rt, sti, @base, line, col, IsSeq(rt, rt.R(@base)));
        return RsOk;
    }
    /// `` `form ``, at the backquote: the form read with a fresh gensym table,
    /// then expanded.
    internal static int ReadSyntaxQuote(Rt rt, int sti) {
        RdNext(rt, sti);
        long gm = global::Flint.Rt.Maps.Empty(rt);
        RdPut(rt, sti, RdsGensyms, gm);
        long n0 = RdInt(rt, sti, RdsConds);
        int @base = rt.Mark();
        int st = ReadOne(rt, sti);
        if (st == RsErr) {
            return RsErr;
        }
        if (st != RsOk) {
            rt.Push(Val.Nil);
        }
        int g = DeferredGuard(rt, sti, n0, "syntax quote");
        if (g != RsOk) {
            rt.PopTo(@base);
            return g;
        }
        int sst = SqForm(rt, sti, @base);
        RdPut(rt, sti, RdsGensyms, Val.Nil);
        if (sst != RsOk) {
            rt.PopTo(@base);
            return sst;
        }
        rt.SetR(@base, rt.R(@base + 1));
        rt.PopTo(@base + 1);
        return RsOk;
    }
    /// `{alias target}` for every `:as` in the `ns` form rooted at `fi`'s
    /// require clauses, as the map the reader resolves `::a/kw` against.
    internal static void NsAliases(Rt rt, int sti, int fi) {
        int @base = rt.Mark();
        long e = global::Flint.Rt.Maps.Empty(rt);
        int acci = rt.Push(e);
        long kreq = LitKeyword1(rt, "require");
        int kreqi = rt.Push(kreq);
        long kuse = LitKeyword1(rt, "use");
        int kusei = rt.Push(kuse);
        long kas = LitKeyword1(rt, "as");
        int kasi = rt.Push(kas);
        long s0 = Seq(rt, rt.R(fi));
        int ci = rt.Push(s0);
        // `(drop 2 form)`.
        long d1 = Next(rt, rt.R(ci));
        rt.SetR(ci, d1);
        long d2 = Next(rt, rt.R(ci));
        rt.SetR(ci, d2);
        for (;;) {
            if (Val.IsNil(rt.R(ci))) {
                break;
            }
            long clause = First(rt, rt.R(ci));
            int cli = rt.Push(clause);
            if (IsSeq(rt, rt.R(cli))) {
                long head = First(rt, rt.R(cli));
                if (ValEq(rt, head, rt.R(kreqi)) || ValEq(rt, head, rt.R(kusei))) {
                    long sp0 = Next(rt, rt.R(cli));
                    int spi = rt.Push(sp0);
                    for (;;) {
                        if (Val.IsNil(rt.R(spi))) {
                            break;
                        }
                        long spec = First(rt, rt.R(spi));
                        int speci = rt.Push(spec);
                        // `(apply hash-map (rest spec))` and its `:as`: the
                        // LAST `:as` wins, and an odd count leaves the final
                        // key's value nil.
                        if (IsVectorLike(rt, rt.R(speci))) {
                            int sn = VecCount(rt, rt.R(speci));
                            long alias;
                            alias = Val.Nil;
                            int j;
                            j = 1;
                            while (j < sn) {
                                if (ValEq(rt, VecNth(rt, rt.R(speci), j, Val.Nil), rt.R(kasi))) {
                                    alias = VecNth(rt, rt.R(speci), j + 1, Val.Nil);
                                }
                                j += 2;
                            }
                            if (!Val.IsNil(alias) && (alias != Val.False)) {
                                int ali = rt.Push(alias);
                                long m2 = MapAssoc(rt, rt.R(acci), rt.R(ali), VecNth(rt, rt.R(speci), 0, Val.Nil));
                                rt.SetR(acci, m2);
                            }
                        }
                        rt.PopTo(speci);
                        long sn2 = Next(rt, rt.R(spi));
                        rt.SetR(spi, sn2);
                    }
                }
            }
            rt.PopTo(cli);
            long cn = Next(rt, rt.R(ci));
            rt.SetR(ci, cn);
        }
        RdPut(rt, sti, RdsAliases, rt.R(acci));
        rt.PopTo(@base);
    }
    /// One top-level form, pushed, or `RS_EOF`. A top-level `(ns ..)` sets the
    /// namespace and aliases `::kw` and `#::{}` resolve against for the rest
    /// of the read -- the FILE's own context, not the compiler's.
    public static int ReadTop(Rt rt, int sti) {
        for (;;) {
            long n0 = RdInt(rt, sti, RdsConds);
            int @base = rt.Mark();
            int st = ReadOne(rt, sti);
            if (st == RsErr) {
                return RsErr;
            }
            if (st == RsEof) {
                if (RdPeek(rt, sti) == NoCp) {
                    return RsEof;
                }
                continue;
            }
            if (st == RsSplice) {
                rt.PopTo(@base);
                return RdFailLit(rt, sti, "#?@ outside a collection");
            }
            // An unmatched `#?@` at the top: the guest's reader handed its
            // marker on as a form, which nothing can encode. Nothing is read
            // here instead.
            if (st == RsNone) {
                continue;
            }
            int vi = @base;
            if (IsSeq(rt, rt.R(vi))) {
                long h = First(rt, rt.R(vi));
                if (IsSym1(rt, h, "ns")) {
                    long nx = Next(rt, rt.R(vi));
                    long nm = First(rt, nx);
                    if (IsSymbol(rt, nm)) {
                        RdPut(rt, sti, RdsNs, nm);
                        NsAliases(rt, sti, vi);
                        if (n0 != RdInt(rt, sti, RdsConds)) {
                            RdPut(rt, sti, RdsApartial, Val.True);
                        } else {
                            RdPut(rt, sti, RdsApartial, Val.False);
                        }
                    }
                }
            }
            if (IsConditional(rt, rt.R(vi))) {
                long items = VecNth(rt, rt.Slot(rt.R(vi), 1), 4, Val.Nil);
                int ii = rt.Push(items);
                int n = VecCount(rt, rt.R(ii));
                for (int i = 0; i < n; i++) {
                    long x = VecNth(rt, rt.R(ii), i, Val.Nil);
                    if (IsSeq(rt, x)) {
                        long xh = First(rt, x);
                        if (IsSym1(rt, xh, "ns")) {
                            rt.PopTo(@base);
                            return RdFailLit(rt, sti, "an ns form inside a reader conditional cannot be read before its features are known (DECISIONS.md#stdlib-preread)");
                        }
                    }
                }
                rt.PopTo(ii);
            }
            return RsOk;
        }
    }
}
